    'CustomizationExtraDesc'              => 'ส่วนเสริมการปรับแต่ง (Customization Extra) ช่วยให้สามารถเพิ่มและลบฟิลด์ประเภทต่างๆ และสร้างเทมเพลตหน้าเว็บแบบกำหนดเองได้แบบไดนามิก',
    'NotificationExtraDesc'               => 'ส่วนเสริมการแจ้งเตือนทางอีเมลช่วยให้ SimpleRisk สามารถส่งการแจ้งเตือนทางอีเมลเมื่อมีการส่ง แก้ไข หรือดำเนินการใดๆ เกี่ยวกับความเสี่ยง ส่วนเสริมนี้ยังสามารถเพิ่มเป็นสคริปต์ที่กำหนดเวลาไว้เพื่อส่งการแจ้งเตือนเป็นประจำเมื่อความเสี่ยงพร้อมสำหรับการตรวจสอบโดยผู้บริหาร ในผลิตภัณฑ์ SimpleRisk Core หากไม่มีส่วนเสริมนี้ จะไม่มีการแจ้งเตือนใดๆ ส่งออกไปยังภายนอกเครื่องมือเลย',
    'VulnerabilityManagementExtraDesc'    => 'Vulnerability Management Extra ช่วยให้ลูกค้าสามารถผสานรวมอินสแตนซ์ SimpleRisk เข้ากับ Qualys, Tenable.io หรือ Rapid7 Nexpose/InsightVM และนำเข้าทั้งข้อมูลสินทรัพย์และข้อมูลช่องโหว่เข้าสู่ SimpleRisk จากนั้นคุณสามารถเลือกไซต์ที่ต้องการครอบคลุม กำหนดว่าจะนำเข้าคะแนนช่องโหว่ใดบ้าง และคัดกรองว่าช่องโหว่ใดจะถูกแปลงเป็นความเสี่ยงเพื่อติดตาม',
    'IncidentManagementExtraDesc'         => 'ส่วนเสริมการจัดการเหตุการณ์ (Incident Management Extra) อ้างอิงจากคู่มือการจัดการเหตุการณ์ด้านความปลอดภัยคอมพิวเตอร์ NIST 800-61 และมอบความสามารถในการจัดการเหตุการณ์จากภายในระบบ SimpleRisk',

    // Configure Hub - tile descriptions (customization category)
