    'RiskConfigurationDesc'               => 'กำหนดค่ากฎการให้คะแนนความเสี่ยง: ระดับ ความเสี่ยงที่ยอมรับได้ เกณฑ์ SLA และสูตรความเสี่ยงแบบคลาสสิก / แบบปัจจัยที่มีส่วนร่วม',
    'RiskAndThreatCatalogDesc'            => 'ดูแลรักษาแคตตาล็อกค่าความเสี่ยงและภัยคุกคามที่ใช้ในรายการแบบเลื่อนลง',
