    'SeparationExtraDesc'                 => 'ส่วนเสริมการแยกตามทีมจะจำกัดการดูความเสี่ยงให้เฉพาะผู้ใช้ที่เป็นสมาชิกของทีมที่ได้รับมอบหมายความเสี่ยงนั้นเท่านั้น ในผลิตภัณฑ์ SimpleRisk Core หากไม่มีส่วนเสริมนี้ ผู้ใช้ทุกคนจะสามารถเห็นความเสี่ยงทั้งหมดได้',
    'CustomAuthenticationExtraDesc'       => 'Custom Authentication Extra ให้การสนับสนุนการยืนยันตัวตนด้วย Active Directory และ SAML ใน SimpleRisk Core หากไม่มี Extra นี้ ตัวเลือกเดียวคือการสร้างผู้ใช้ใหม่ในที่เก็บข้อมูลระบุตัวตนของ SimpleRisk',
    'EncryptionExtraDesc'                 => 'Encrypted Database Extra สร้างคีย์เข้ารหัส AES-256 บิตแบบสุ่ม แล้วใช้คีย์นั้นเข้ารหัสข้อความที่ละเอียดอ่อนก่อนจะบันทึกลงในฐานข้อมูล SimpleRisk ซึ่งช่วยป้องกันไม่ให้ผู้ใดดูหรือแก้ไขข้อมูลได้หากไม่ได้ใช้แอปพลิเคชัน SimpleRisk โดยตรง',
    'OrganizationManagementDesc'          => "ส่วนเสริมลำดับชั้นองค์กรช่วยให้สามารถกำหนดหน่วยธุรกิจได้หลายหน่วย ซึ่งสามารถรวมทีมได้หลายทีม จากนั้นผู้ใช้สามารถได้รับการกำหนดให้ทำงานในทีมหนึ่งหรือหลายทีมภายใต้หน่วยธุรกิจต่างๆ ซึ่งจะมีผลต่อความสามารถของผู้ใช้ในการดูและใช้งานทีม ผู้ใช้ และสินทรัพย์ที่ตนเองไม่ได้เกี่ยวข้องด้วย",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'ลบความเสี่ยงจำนวนมากพร้อมกัน โปรดใช้อย่างระมัดระวัง เพราะการลบเป็นการถาวร',
    'AuditTrailDesc'                      => 'ค้นหาและส่งออกบันทึกการตรวจสอบระบบของการดำเนินการของผู้ใช้',
    'ImportExportExtraDesc'               => 'Import-Export Extra ช่วยให้สามารถนำเข้าข้อมูลสู่ SimpleRisk โดยการแมปฟิลด์ในไฟล์ CSV กับฟิลด์ในฐานข้อมูล SimpleRisk ใช้นำเข้าผลลัพธ์การตรวจสอบจากสเปรดชีตของบุคคลที่สาม ผลการสแกนช่องโหว่จากเครื่องมืออื่น สินทรัพย์จาก CMDB ของคุณ และอื่นๆ นอกจากนี้ Extra ยังสามารถส่งออกไฟล์ CSV จาก SimpleRisk ที่มีความเสี่ยง การบรรเทาผลกระทบ การทบทวน หรือรายงานรวมของทั้งสามอย่าง',
    'JiraExtraDesc'                       => 'Jira Integration Extra ช่วยให้ผู้ใช้สามารถผสานรวมแบบสองทิศทางกับอินสแตนซ์ Jira ได้ โดยเชื่อมโยงความเสี่ยงกับปัญหา Jira รวมถึงซิงค์ข้อมูล สถานะ และความคิดเห็นของความเสี่ยงเหล่านั้น',
    'APIExtraDesc'                        => 'API Extra ช่วยให้ลูกค้าสามารถใช้ RESTful API เพื่อสร้างปฏิสัมพันธ์แบบสคริปต์กับแอปพลิเคชันอื่นๆ เพื่อให้ได้ระบบอัตโนมัติขั้นสูงและใช้ประโยชน์จากโครงสร้างพื้นฐานที่มีอยู่',
    'AdvancedSearchExtraDesc'             => 'Advanced Search Extra เปลี่ยนช่องค้นหาบนแถบด้านบนให้เป็นการค้นหาเดียวที่ครอบคลุมความเสี่ยง เฟรมเวิร์ก การควบคุม เอกสาร ข้อยกเว้น การทดสอบ การตรวจสอบ สินทรัพย์ และกลุ่มสินทรัพย์ พร้อมหน้าค้นหาแบบเต็มสำหรับดูผลลัพธ์ โดยจะแสดงเฉพาะระเบียนที่ผู้ใช้ได้รับอนุญาตให้ดูเท่านั้น',
    'AssessmentsExtraDesc'                => 'ส่วนเสริมการประเมินความเสี่ยง (Risk Assessment Extra) ช่วยให้ผู้ใช้สามารถกำหนดผู้ติดต่อ สร้างคำถาม (รวมถึงตรรกะ) รวบรวมคำถามหลายข้อโดยใช้แม่แบบแบบสอบถาม สร้างแบบสอบถามและส่งไปยังผู้ติดต่อ ดูผลลัพธ์ของแบบสอบถาม เพิ่มความเสี่ยงตามผลลัพธ์เหล่านั้น และเปรียบเทียบผลลัพธ์ในช่วงเวลาต่างๆ นำเข้าและส่งออกการประเมินที่ปรับแต่งจากภายนอก และตรวจสอบเส้นทางการตรวจสอบการประเมินความเสี่ยง',
    'ActiveAssessmentsDesc'               => 'ดูและจัดการการประเมินผลที่กำลังดำเนินการอยู่',
    'WorkflowsExtraDesc'                  => 'Workflows Extra มอบเอ็นจินเวิร์กโฟลว์แบบภาพที่ขับเคลื่อนด้วยเหตุการณ์ ซึ่งทำให้การดำเนินการด้านการจัดการความเสี่ยงเป็นอัตโนมัติเพื่อตอบสนองต่อเหตุการณ์ภายใน SimpleRisk คุณสามารถออกแบบเวิร์กโฟลว์ที่ทริกเกอร์เมื่อมีการเปลี่ยนแปลง เช่น การส่ง อัปเดต หรือทบทวนความเสี่ยง เพื่อกำหนดเส้นทางการอนุมัติ มอบหมายงาน และให้กระบวนการดำเนินต่อไปโดยไม่ต้องแทรกแซงด้วยตนเอง',

    // Configure Hub - tile descriptions (frameworks category)
