    'SoaChooseFramework' => 'เลือกเฟรมเวิร์ก',
    'SoaChooseFrameworkHint' => 'เอกสารแถลงการณ์การประยุกต์ใช้จะจัดทำสำหรับหนึ่งเฟรมเวิร์กในแต่ละครั้ง',
    // The picker has a roster but nothing in it. Distinct from "this framework
