    'SoaFrameworkInactiveTitle' => 'เฟรมเวิร์กนี้ไม่ได้ใช้งาน',
    'SoaFrameworkInactiveBody' => 'เอกสารแถลงการณ์การประยุกต์ใช้อธิบายขอบเขตที่องค์กรดำเนินงานอยู่ในปัจจุบัน เปิดใช้งานเฟรมเวิร์กอีกครั้งเพื่อสร้างเอกสาร',
    'SoaFrameworkNotFoundBody' => 'ไม่มีเฟรมเวิร์กนั้นอยู่อีกต่อไป',

    // A framework with no controls mapped into it. Not an error -- it is a real
