    'SoaNoControls' => 'เฟรมเวิร์กนี้ไม่มีการควบคุม',
    'SoaNoControlsHint' => 'แมปการควบคุมเข้ากับเฟรมเวิร์ก แล้วแถลงการณ์การประยุกต์ใช้ของเฟรมเวิร์กจะแสดงรายการเหล่านั้น',

    // The second half of the statement-of-applicability launcher's affordance
