    "AttackVectorHelp" => "วิธีการเข้าถึงช่องโหว่\n• โลคอล: ต้องเข้าถึงภายในเครื่อง เช่น คอนโซลหรือเชลล์\n• เครือข่ายข้างเคียง: ผู้โจมตีต้องอยู่ในส่วนเครือข่ายทางกายภาพหรือตรรกะเดียวกัน\n• เครือข่าย: สามารถโจมตีจากระยะไกลผ่านเครือข่ายได้ โดยไม่จำเป็นต้องเข้าถึงภายในเครื่องหรือเครือข่ายข้างเคียง",
    "AttackComplexityHelp" => "ความซับซ้อนของการโจมตีเมื่อผู้โจมตีเข้าถึงเป้าหมายได้แล้ว\n• สูง: ต้องมีเงื่อนไขเฉพาะที่จัดเตรียมได้ยาก\n• ปานกลาง: ต้องมีเงื่อนไขบางอย่าง แต่การโจมตีจะไม่ยากเมื่อเงื่อนไขเหล่านั้นครบถ้วนแล้ว\n• ต่ำ: ไม่จำเป็นต้องมีเงื่อนไขพิเศษใดๆ",
    "AuthenticationHelp" => "จำนวนครั้งที่ผู้โจมตีต้องยืนยันตัวตนกับเป้าหมายเพื่อใช้ประโยชน์จากช่องโหว่นั้น\n• หลายครั้ง: ต้องยืนยันตัวตนสองครั้งขึ้นไป แม้ว่าจะใช้ข้อมูลประจำตัวเดียวกันก็ตาม\n• ครั้งเดียว: ต้องยืนยันตัวตนเพียงครั้งเดียว\n• ไม่มี: ไม่ต้องยืนยันตัวตน",
    "ConfidentialityImpactHelp" => 'ผลกระทบต่อการรักษาความลับของข้อมูลที่ระบบประมวลผลหากถูกโจมตี
• ไม่มี: ไม่มีผลกระทบ
• บางส่วน: มีการเปิดเผยข้อมูลบางส่วน แต่ผู้โจมตีไม่สามารถควบคุมได้ว่าเป็นข้อมูลใด หรือความสูญเสียมีจำกัด
• ทั้งหมด: มีการเปิดเผยข้อมูลทั้งหมดในระบบ',
    "IntegrityImpactHelp" => 'ผลกระทบต่อความถูกต้องสมบูรณ์ของระบบหากถูกโจมตี
• ไม่มี: ไม่มีผลกระทบ
• บางส่วน: ข้อมูลบางส่วนอาจถูกแก้ไขได้ แต่ผู้โจมตีไม่สามารถควบคุมได้ว่าเป็นข้อมูลใด หรือขอบเขตมีจำกัด
• ทั้งหมด: ความถูกต้องสมบูรณ์ของระบบถูกบุกรุกโดยสิ้นเชิง ผู้โจมตีสามารถแก้ไขไฟล์ใดก็ได้',
    "AvailabilityImpactHelp" => 'ผลกระทบต่อความพร้อมใช้งานของระบบหากถูกโจมตี
• ไม่มี: ไม่มีผลกระทบ
• บางส่วน: ประสิทธิภาพลดลงหรือความพร้อมใช้งานหยุดชะงัก
• ทั้งหมด: ทรัพยากรที่ได้รับผลกระทบหยุดทำงานโดยสมบูรณ์',
    "RemediationLevelHelp" => "ระดับของการแก้ไขช่องโหว่ที่มีอยู่\n• การแก้ไขอย่างเป็นทางการ: มีโซลูชันที่สมบูรณ์จากผู้จำหน่าย\n• การแก้ไขชั่วคราว: มีการแก้ไขอย่างเป็นทางการแต่เป็นการแก้ไขชั่วคราว\n• วิธีแก้ปัญหาเฉพาะหน้า: มีวิธีแก้ปัญหาเฉพาะหน้าที่ไม่เป็นทางการและไม่ได้มาจากผู้จำหน่าย\n• ไม่พร้อมใช้งาน: ไม่มีโซลูชัน หรือไม่สามารถนำโซลูชันใดมาใช้ได้",
    "ReportConfidenceHelp" => 'ระดับความเชื่อมั่นในการมีอยู่ของช่องโหว่และความน่าเชื่อถือของรายละเอียดทางเทคนิค
• ยังไม่ยืนยัน: รายงานจากแหล่งเดียวที่ยังไม่ได้รับการยืนยัน ปัญหาพื้นฐานยังเป็นเพียงการคาดการณ์
• ยังไม่มีหลักฐานสนับสนุน: มีหลายแหล่งอิสระรายงานพฤติกรรมเดียวกัน แต่ยังไม่ยืนยันสาเหตุที่แท้จริง
• ยืนยันแล้ว: ผู้จำหน่ายยอมรับปัญหาแล้ว หรือได้รับการยืนยันจากการวิเคราะห์ซอร์สโค้ดหรือช่องโหว่',
    "CollateralDamagePotentialHelp" => 'ศักยภาพที่จะเกิดการสูญเสียชีวิต สินทรัพย์ทางกายภาพ หรือความสูญเสียทางการเงินหากช่องโหว่ถูกโจมตี
• ไม่มี: ไม่น่าจะเกิดความสูญเสียดังกล่าว
• ต่ำถึงปานกลาง: อาจเกิดความสูญเสียในระดับปานกลาง
• สูง: ผลกระทบร้ายแรงอย่างมากต่อสินทรัพย์ รายได้ หรือความปลอดภัยขององค์กร',
    "TargetDistributionHelp" => 'สัดส่วนของระบบที่มีช่องโหว่ในสภาพแวดล้อมของคุณ
• ไม่มี: ไม่มีระบบเป้าหมายอยู่
• ต่ำ: ระบบมีช่องโหว่ 1-25%
• ปานกลาง: มีช่องโหว่ 26-75%
• สูง: มีช่องโหว่ 76-100%',
    "ConfidentialityRequirementHelp" => 'การรักษาความลับของสินทรัพย์ที่ได้รับผลกระทบมีความสำคัญต่อองค์กรของคุณเพียงใด
• ต่ำ: การสูญเสียการรักษาความลับมีผลกระทบจำกัด
• ปานกลาง: มีผลกระทบรุนแรง
• สูง: มีผลกระทบร้ายแรงอย่างมาก',
    "IntegrityRequirementHelp" => 'ความถูกต้องสมบูรณ์ของสินทรัพย์ที่ได้รับผลกระทบมีความสำคัญต่อองค์กรของคุณเพียงใด
• ต่ำ: การสูญเสียความถูกต้องสมบูรณ์มีผลกระทบจำกัด
• ปานกลาง: มีผลกระทบรุนแรง
• สูง: มีผลกระทบร้ายแรงอย่างมาก',
    "AvailabilityRequirementHelp" => 'ความพร้อมใช้งานของสินทรัพย์ที่ได้รับผลกระทบมีความสำคัญต่อองค์กรของคุณเพียงใด
• ต่ำ: การสูญเสียความพร้อมใช้งานมีผลกระทบจำกัด
• ปานกลาง: มีผลกระทบรุนแรง
• สูง: มีผลกระทบร้ายแรงอย่างมาก',
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'ผู้โจมตีจะต้องเข้าถึงและกระตุ้นช่องโหว่นี้ได้อย่างไร: พวกเขาต้องอยู่ที่ไหน การโจมตีมีความซับซ้อนแค่ไหน และพวกเขาจำเป็นต้องยืนยันตัวตนก่อนหรือไม่',
    'BaseScoreImpactMetricsDescription' => 'จะเกิดอะไรขึ้นหากมีการโจมตีช่องโหว่สำเร็จ: ผลกระทบต่อความลับ ความถูกต้องครบถ้วน และความพร้อมใช้งานของระบบที่ได้รับผลกระทบ',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'ภัยคุกคามในโลกแห่งความเป็นจริงของช่องโหว่นี้เปลี่ยนแปลงไปอย่างไรเมื่อเวลาผ่านไป: สถานะปัจจุบันของโค้ดที่ใช้ในการโจมตี การแก้ไขที่มีอยู่ และความมั่นใจของรายงานต่างๆ ว่าช่องโหว่นี้มีอยู่จริง',
    'EnvironmentalScoreMetricsDescription' => 'ความเสี่ยงของช่องโหว่นี้ขึ้นอยู่กับสภาพแวดล้อมของคุณอย่างไร: ศักยภาพในการสร้างความเสียหายจริง และมีระบบของคุณได้รับผลกระทบจริงกี่ระบบ',
    'ImpactSubscoreModifiersDescription' => 'ถ่วงน้ำหนักผลกระทบของคะแนนพื้นฐานตามความสำคัญที่แท้จริงของความลับ ความถูกต้องครบถ้วน และความพร้อมใช้งานสำหรับสินทรัพย์นี้โดยเฉพาะ',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'หากเกิดการโจมตีภัยคุกคาม จะก่อให้เกิดความเสียหายมากเพียงใด
0 = ไม่มีเลย
5 = ข้อมูลของผู้ใช้รายบุคคลถูกบุกรุกหรือได้รับผลกระทบ
10 = ระบบหรือข้อมูลถูกทำลายทั้งหมด',
    'ReproducibilityHelp' => 'การทำซ้ำการโจมตีภัยคุกคามทำได้ง่ายเพียงใด
0 = ยากมากหรือเป็นไปไม่ได้ แม้สำหรับผู้ดูแลระบบของแอปพลิเคชัน
5 = ต้องใช้หนึ่งหรือสองขั้นตอน อาจต้องเป็นผู้ใช้ที่ได้รับอนุญาต
10 = เพียงเว็บเบราว์เซอร์และแถบที่อยู่ก็เพียงพอ โดยไม่ต้องยืนยันตัวตน',
    'ExploitabilityHelp' => 'ต้องใช้สิ่งใดบ้างในการใช้ประโยชน์จากภัยคุกคามนี้?' . "\n" . '0 = ความรู้ด้านการเขียนโปรแกรมและเครือข่ายขั้นสูง พร้อมเครื่องมือโจมตีแบบกำหนดเองหรือขั้นสูง' . "\n" . '5 = มีมัลแวร์อยู่บนอินเทอร์เน็ต หรือสามารถเจาะระบบได้ง่ายโดยใช้เครื่องมือโจมตีที่มีอยู่' . "\n" . '10 = แค่เว็บเบราว์เซอร์',
    'AffectedUsersHelp' => 'มีผู้ใช้ได้รับผลกระทบกี่ราย
0 = ไม่มี
5 = ผู้ใช้บางราย แต่ไม่ใช่ทั้งหมด
10 = ผู้ใช้ทั้งหมด',
    'DiscoverabilityHelp' => 'การค้นพบภัยคุกคามนี้ทำได้ง่ายแค่ไหน?' . "\n" . '0 = ยากมากถึงเป็นไปไม่ได้ ต้องใช้ซอร์สโค้ดหรือสิทธิ์การเข้าถึงระดับผู้ดูแลระบบ' . "\n" . '5 = สามารถหาคำตอบได้โดยการเดาหรือตรวจสอบข้อมูลการใช้งานเครือข่าย' . "\n" . '9 = รายละเอียดของข้อผิดพลาดประเภทนี้มีอยู่ในแหล่งข้อมูลสาธารณะอยู่แล้ว และสามารถค้นหาได้ง่ายๆ โดยใช้เครื่องมือค้นหา' . "\n" . '10 = ข้อมูลจะปรากฏให้เห็นในแถบที่อยู่ของเว็บเบราว์เซอร์หรือในแบบฟอร์ม',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
