    'SkillLevelHelp' => 'กลุ่มตัวการภัยคุกคามนี้มีทักษะทางเทคนิคมากเพียงใด
1 = ไม่มีทักษะทางเทคนิค
3 = มีทักษะทางเทคนิคบ้าง
5 = ผู้ใช้คอมพิวเตอร์ขั้นสูง
6 = ทักษะด้านเครือข่ายและการเขียนโปรแกรม
9 = ทักษะการทดสอบเจาะระบบด้านความปลอดภัย',
    'MotiveHelp' => 'กลุ่มตัวการภัยคุกคามนี้มีแรงจูงใจในการค้นหาและโจมตีช่องโหว่นี้มากเพียงใด
