    'OpportunityHelp' => 'กลุ่มตัวการภัยคุกคามนี้ต้องมีทรัพยากรและโอกาสอะไรบ้างในการค้นหาและโจมตีช่องโหว่นี้
0 = ต้องมีการเข้าถึงเต็มรูปแบบหรือทรัพยากรที่มีราคาแพง
4 = ต้องมีการเข้าถึงหรือทรัพยากรพิเศษ
7 = ต้องมีการเข้าถึงหรือทรัพยากรบางส่วน
9 = ไม่ต้องมีการเข้าถึงหรือทรัพยากร',
    'SizeHelp' => 'กลุ่มตัวการภัยคุกคามนี้มีขนาดใหญ่เพียงใด
2 = นักพัฒนา
2 = ผู้ดูแลระบบ
