5 = พันธมิตร
6 = ผู้ใช้ที่ยืนยันตัวตนแล้ว
9 = ผู้ใช้อินเทอร์เน็ตนิรนาม',
    'EaseOfDiscoveryHelp' => 'กลุ่มตัวการภัยคุกคามนี้ค้นพบช่องโหว่นี้ได้ง่ายเพียงใด
