8 = บันทึกแต่ไม่ตรวจสอบ
9 = ไม่บันทึก',
    'LossOfConfidentialityHelp' => 'ข้อมูลอาจถูกเปิดเผยมากเพียงใดและมีความอ่อนไหวเพียงใด
2 = เปิดเผยข้อมูลที่ไม่อ่อนไหวจำนวนน้อย
6 = เปิดเผยข้อมูลสำคัญจำนวนน้อย
6 = เปิดเผยข้อมูลที่ไม่อ่อนไหวจำนวนมาก
7 = เปิดเผยข้อมูลสำคัญจำนวนมาก
9 = เปิดเผยข้อมูลทั้งหมด',
    'LossOfIntegrityHelp' => 'ข้อมูลอาจเสียหายมากเพียงใดและเสียหายรุนแรงเพียงใด
