    'NonComplianceHelp' => 'การไม่ปฏิบัติตามกฎระเบียบก่อให้เกิดความเสี่ยงมากน้อยเพียงใด?' . "\n" . '2 = การละเมิดเล็กน้อย' . "\n" . '5 = การละเมิดอย่างชัดเจน' . "\n" . '7 = การละเมิดที่มีความสำคัญสูง',
